<?php
declare(strict_types=1);
session_start();
require_once __DIR__ . '/../app/helpers.php'; require_once __DIR__ . '/../app/mail.php';
initialize_database(); $pdo=db(); $page=$_GET['page']??(current_user()?'directory':'login');
if ($page==='logout') { session_destroy(); session_start(); flash('success','Vous êtes déconnecté.'); redirect('?page=login'); }

if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf(); $action=$_POST['action']??''; $me=current_user();
    if ($action==='login') { $s=$pdo->prepare('SELECT * FROM users WHERE email=?'); $s->execute([trim($_POST['email']??'')]); $u=$s->fetch(); if ($u && $u['status']==='active' && password_verify($_POST['password']??'', $u['password_hash'])) { session_regenerate_id(true); $_SESSION['user_id']=$u['id']; $pdo->prepare('UPDATE users SET last_login_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$u['id']]); flash('success','Bienvenue '. $u['first_name'].' !'); redirect('?page=directory'); } flash('error','Identifiants invalides ou compte non activé.'); redirect('?page=login'); }
    if ($action==='forgot') { $s=$pdo->prepare("SELECT * FROM users WHERE email=? AND status='active'"); $s->execute([trim($_POST['email']??'')]); if ($u=$s->fetch()) { $t=token(); $pdo->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(?,?,?)')->execute([$u['id'],token_hash($t),date('Y-m-d H:i:s',time()+TOKEN_TTL)]); send_mail($u['email'],'Réinitialisation de votre mot de passe',"Bonjour,\n\nDéfinissez un nouveau mot de passe : ".app_url()."/?page=reset&token=$t\nCe lien expire dans 24 heures.",'password_reset'); } flash('success','Si cette adresse existe, un e-mail de réinitialisation a été envoyé.'); redirect('?page=forgot'); }
    if ($action==='reset') { $r=valid_token('password_resets',$_POST['token']??''); $pass=$_POST['password']??''; if (!$r || strlen($pass)<10) { flash('error','Lien invalide ou mot de passe trop court (10 caractères minimum).'); redirect('?page=forgot'); } $pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($pass,PASSWORD_DEFAULT),$r['user_id']]); $pdo->prepare('UPDATE password_resets SET used_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$r['id']]); flash('success','Mot de passe modifié. Connectez-vous.'); redirect('?page=login'); }
    if ($action==='accept_invitation') { $i=valid_token('invitations',$_POST['token']??''); $pass=$_POST['password']??''; if (!$i || strlen($pass)<10 || trim($_POST['first_name']??'')==='' || trim($_POST['last_name']??'')==='') { flash('error','Lien invalide ou formulaire incomplet (mot de passe : 10 caractères minimum).'); redirect('?page=login'); } $s=$pdo->prepare('SELECT id FROM users WHERE email=?'); $s->execute([$i['email']]); $old=$s->fetch(); if ($old) $uid=$old['id']; else { $pdo->prepare('INSERT INTO users(email,first_name,last_name,phone,password_hash,status) VALUES(?,?,?,?,?,\'active\')')->execute([$i['email'],trim($_POST['first_name']),trim($_POST['last_name']),trim($_POST['phone']),password_hash($pass,PASSWORD_DEFAULT)]); $uid=(int)$pdo->lastInsertId(); } $pdo->prepare("UPDATE users SET first_name=?,last_name=?,phone=?,password_hash=?,status='active' WHERE id=?")->execute([trim($_POST['first_name']),trim($_POST['last_name']),trim($_POST['phone']),password_hash($pass,PASSWORD_DEFAULT),$uid]); $pdo->prepare(is_mysql() ? 'INSERT IGNORE INTO profiles(user_id) VALUES(?)' : 'INSERT OR IGNORE INTO profiles(user_id) VALUES(?)')->execute([$uid]); $pdo->prepare("UPDATE invitations SET status='used',used_at=".sql_now().' WHERE id=?')->execute([$i['id']]); flash('success','Votre compte est activé.'); redirect('?page=login'); }
    if ($action==='profile') { $u=require_user(); $address=trim($_POST['address']??''); $lat=filter_var($_POST['latitude']??'',FILTER_VALIDATE_FLOAT); $lon=filter_var($_POST['longitude']??'',FILTER_VALIDATE_FLOAT); if (($lat===false || $lon===false) && $address) { $geo=geocode($address); $lat=$geo['lat']??null; $lon=$geo['lon']??null; } $availability=$_POST['availability']??'passenger'; if (!in_array($availability,['driver','passenger','both'],true)) $availability='passenger'; $values=[$u['id'],$address,$lat===false?null:$lat,$lon===false?null:$lon,approximate($lat===false?null:$lat),approximate($lon===false?null:$lon),$availability,max(0,(int)$_POST['seats']),trim($_POST['detour']),trim($_POST['comment'])]; $pdo->prepare('UPDATE users SET first_name=?,last_name=?,phone=? WHERE id=?')->execute([trim($_POST['first_name']),trim($_POST['last_name']),trim($_POST['phone']),$u['id']]); $profileSql=is_mysql() ? 'INSERT INTO profiles(user_id,address,latitude,longitude,approx_latitude,approx_longitude,availability,seats,detour,comment) VALUES(?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE address=VALUES(address),latitude=VALUES(latitude),longitude=VALUES(longitude),approx_latitude=VALUES(approx_latitude),approx_longitude=VALUES(approx_longitude),availability=VALUES(availability),seats=VALUES(seats),detour=VALUES(detour),comment=VALUES(comment)' : 'INSERT INTO profiles(user_id,address,latitude,longitude,approx_latitude,approx_longitude,availability,seats,detour,comment,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(user_id) DO UPDATE SET address=excluded.address,latitude=excluded.latitude,longitude=excluded.longitude,approx_latitude=excluded.approx_latitude,approx_longitude=excluded.approx_longitude,availability=excluded.availability,seats=excluded.seats,detour=excluded.detour,comment=excluded.comment,updated_at=CURRENT_TIMESTAMP'; $pdo->prepare($profileSql)->execute($values); flash('success','Profil enregistré.'); redirect('?page=profile'); }
    if ($action==='invite') { $a=require_admin(); $email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL); if (!$email) { flash('error','Adresse e-mail invalide.'); redirect('?page=admin'); } $t=token(); $pdo->prepare('INSERT INTO invitations(email,token_hash,expires_at,created_by) VALUES(?,?,?,?)')->execute([$email,token_hash($t),date('Y-m-d H:i:s',time()+TOKEN_TTL),$a['id']]); send_mail($email,'Invitation à la chorale',"Bonjour,\n\nActivez votre compte : ".app_url()."/?page=invite&token=$t\nCe lien expire dans 24 heures.",'invitation'); flash('success','Invitation créée et envoyée à MailHog.'); redirect('?page=admin'); }
    if ($action==='event') { $a=require_admin(); $id=(int)($_POST['id']??0); $values=[trim($_POST['title']),$_POST['type']==='concert'?'concert':'repetition',trim($_POST['starts_at']),trim($_POST['location']),trim($_POST['details']),$_POST['status']==='cancelled'?'cancelled':'active']; if (!$values[0]||!$values[2]||!$values[3]) { flash('error','Titre, date et lieu sont obligatoires.'); redirect('?page=admin'); } if($id) {$values[]=$id; $pdo->prepare('UPDATE events SET title=?,type=?,starts_at=?,location=?,details=?,status=? WHERE id=?')->execute($values);} else {$values[]=$a['id'];$pdo->prepare('INSERT INTO events(title,type,starts_at,location,details,status,created_by) VALUES(?,?,?,?,?,?,?)')->execute($values);} flash('success','Événement enregistré.'); redirect('?page=admin'); }
    if ($action==='member_status') { require_admin(); $pdo->prepare("UPDATE users SET status=? WHERE id=? AND role='member'")->execute([$_POST['status']==='disabled'?'disabled':'active',(int)$_POST['user_id']]); flash('success','État du membre modifié.'); redirect('?page=admin'); }
    if ($action==='request') { $u=require_user(); $recipient=(int)$_POST['recipient_id']; $event=(int)$_POST['event_id']; if($recipient===$u['id']||!trim($_POST['pickup_place'])||!trim($_POST['pickup_time'])) { flash('error','Formulaire de demande invalide.'); redirect('?page=directory'); } $check=$pdo->prepare("SELECT u.email,e.title FROM users u,events e WHERE u.id=? AND u.status='active' AND e.id=? AND e.status='active' AND e.starts_at >= ".sql_now());$check->execute([$recipient,$event]); if(!($r=$check->fetch())) { flash('error','Destinataire ou événement indisponible.'); redirect('?page=directory'); } $pdo->prepare('INSERT INTO carpool_requests(event_id,requester_id,recipient_id,pickup_place,pickup_time,message) VALUES(?,?,?,?,?,?)')->execute([$event,$u['id'],$recipient,trim($_POST['pickup_place']),trim($_POST['pickup_time']),trim($_POST['message'])]); $id=(int)$pdo->lastInsertId(); send_mail($r['email'],'Nouvelle demande de covoiturage',"Vous avez une demande pour {$r['title']}. Consultez-la : ".app_url()."/?page=request&id=$id",'request'); flash('success','Demande envoyée.'); redirect('?page=requests'); }
    if ($action==='respond') { $u=require_user(); $id=(int)$_POST['request_id']; $s=$pdo->prepare('SELECT cr.*, e.title, ru.email requester_email FROM carpool_requests cr JOIN events e ON e.id=cr.event_id JOIN users ru ON ru.id=cr.requester_id WHERE cr.id=?');$s->execute([$id]); $r=$s->fetch(); $decision=$_POST['decision']??''; if(!$r || !in_array($decision,['acceptee','refusee','contre_proposition','annulee'],true) || !($u['role']==='admin'||$r['recipient_id']==$u['id']||($decision==='annulee'&&$r['requester_id']==$u['id']))) { http_response_code(403); exit('Action non autorisée.'); } $pdo->prepare('INSERT INTO request_responses(request_id,author_id,decision,message,proposed_place,proposed_time) VALUES(?,?,?,?,?,?)')->execute([$id,$u['id'],$decision,trim($_POST['message']),trim($_POST['proposed_place']),trim($_POST['proposed_time'])]); $pdo->prepare('UPDATE carpool_requests SET status=?,updated_at='.sql_now().' WHERE id=?')->execute([$decision,$id]); send_mail($r['requester_email'],'Réponse à votre demande',"Réponse pour {$r['title']} : ".str_replace('_',' ',$decision).". Consultez le détail : ".app_url()."/?page=request&id=$id",'response'); flash('success','Réponse enregistrée.'); redirect('?page=request&id='.$id); }
}

