if ($page==='profile') { $u=require_user(); $s=$pdo->prepare('SELECT * FROM profiles WHERE user_id=?');$s->execute([$u['id']]);$p=$s->fetch()?:[]; $opts='';foreach(['driver'=>'Je propose une place','passenger'=>'Je cherche une place','both'=>'Les deux'] as $v=>$l)$opts.='<option value="'.$v.'" '.(($p['availability']??'')===$v?'selected':'').'>'.$l.'</option>'; layout('Mon profil','<h1>Mon profil</h1><p class="hint">Votre adresse exacte ne sera jamais affichée sur la carte ; seule une position arrondie y est utilisée.</p><form method="post">'.csrf_field().'<input type="hidden" name="action" value="profile">'.input('first_name','Prénom',$u['first_name'],'text',true).input('last_name','Nom',$u['last_name'],'text',true).input('phone','Téléphone',$u['phone']??'').input('address','Adresse',$p['address']??'').'<div class="grid">'.input('latitude','Latitude (corrigeable)',$p['latitude']??'','number').input('longitude','Longitude (corrigeable)',$p['longitude']??'','number').'</div><label>Disponibilité<select name="availability">'.$opts.'</select></label>'.input('seats','Places proposées',$p['seats']??0,'number').input('detour','Zone ou détour accepté',$p['detour']??'').'<label>Commentaire<textarea name="comment">'.h($p['comment']??'').'</textarea></label><button>Enregistrer</button></form>'); exit; }
if ($page==='directory') { $u=require_user(); $filter=$_GET['filter']??''; $sql="SELECT u.id,u.first_name,u.last_name,p.availability,p.seats,p.detour,p.comment,p.approx_latitude,p.approx_longitude FROM users u JOIN profiles p ON p.user_id=u.id WHERE u.status='active' AND u.id != ?"; $args=[$u['id']]; if(in_array($filter,['driver','passenger'],true)){ $sql.=' AND (p.availability=? OR p.availability=\'both\')';$args[]=$filter; } $s=$pdo->prepare($sql);$s->execute($args);$people=$s->fetchAll(); $cards='';$markers=[];foreach($people as $p){$cards.='<article><h3>'.h($p['first_name'].' '.$p['last_name']).'</h3><p>'.h($p['availability']).($p['seats']?' · '.(int)$p['seats'].' place(s)':'').'</p><p>'.h($p['detour']).'</p><a href="?page=member&id='.(int)$p['id'].'">Voir la fiche</a></article>';if($p['approx_latitude']!==null)$markers[]=['lat'=>$p['approx_latitude'],'lon'=>$p['approx_longitude'],'name'=>$p['first_name'].' '.$p['last_name']];} $data=json_encode($markers,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT); layout('Annuaire','<h1>Annuaire des disponibilités</h1><p><a href="?page=directory">Tous</a> · <a href="?page=directory&filter=driver">Conducteurs</a> · <a href="?page=directory&filter=passenger">Passagers</a></p><div id="map"></div><section class="cards">'.($cards?:'<p>Aucune personne disponible pour ce filtre.</p>').'</section><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const points='.$data.';const map=L.map("map").setView([46.6,2.4],5);L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{attribution:"© OpenStreetMap"}).addTo(map);points.forEach(p=>L.marker([p.lat,p.lon]).addTo(map).bindPopup(p.name));if(points.length)map.fitBounds(points.map(p=>[p.lat,p.lon]),{padding:[20,20],maxZoom:12});</script>');exit; }
if ($page==='member') { $u=require_user();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT u.*,p.* FROM users u JOIN profiles p ON p.user_id=u.id WHERE u.id=? AND u.status=\'active\'');$s->execute([$id]);$m=$s->fetch();if(!$m||$id===$u['id']){http_response_code(404);exit('Membre introuvable.');}$ev=$pdo->query("SELECT * FROM events WHERE status='active' AND starts_at >= ".sql_now().' ORDER BY starts_at')->fetchAll();$options='';foreach($ev as $e)$options.='<option value="'.$e['id'].'">'.h($e['title'].' — '.$e['starts_at']).'</option>';layout('Fiche membre','<h1>'.h($m['first_name'].' '.$m['last_name']).'</h1><p><strong>Disponibilité :</strong> '.h($m['availability']).'</p><p>'.h($m['comment']).'</p><p><strong>Contact :</strong> '.h($m['email']).($m['phone']?' · '.h($m['phone']):'').'</p><h2>Demander un covoiturage</h2>'.($options?'<form method="post">'.csrf_field().'<input type="hidden" name="action" value="request"><input type="hidden" name="recipient_id" value="'.$id.'"><label>Événement<select name="event_id" required>'.$options.'</select></label>'.input('pickup_place','Lieu de passage','','text',true).input('pickup_time','Heure souhaitée','','time',true).'<label>Message<textarea name="message"></textarea></label><button>Envoyer la demande</button></form>':'<p>Aucun événement à venir.</p>'));exit; }
if ($page==='requests') { $u=require_user();$s=$pdo->prepare('SELECT cr.*,e.title,e.starts_at, '.sql_full_name('a').' other FROM carpool_requests cr JOIN events e ON e.id=cr.event_id JOIN users a ON a.id=CASE WHEN cr.requester_id=? THEN cr.recipient_id ELSE cr.requester_id END WHERE cr.requester_id=? OR cr.recipient_id=? ORDER BY cr.updated_at DESC');$s->execute([$u['id'],$u['id'],$u['id']]);$rows='';foreach($s as $r)$rows.='<tr><td>'.h($r['title']).'</td><td>'.h($r['other']).'</td><td>'.h(str_replace('_',' ',$r['status'])).'</td><td><a href="?page=request&id='.$r['id'].'">Détail</a></td></tr>';layout('Mes demandes','<h1>Mes demandes</h1><table><tr><th>Événement</th><th>Interlocuteur</th><th>État</th><th></th></tr>'.($rows?:'<tr><td colspan="4">Aucune demande.</td></tr>').'</table>');exit; }
if ($page==='request') { $u=require_user();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT cr.*,e.title,e.starts_at,e.location, '.sql_full_name('a').' requester, '.sql_full_name('b').' recipient FROM carpool_requests cr JOIN events e ON e.id=cr.event_id JOIN users a ON a.id=cr.requester_id JOIN users b ON b.id=cr.recipient_id WHERE cr.id=?');$s->execute([$id]);$r=$s->fetch();if(!$r||!($u['role']==='admin'||$u['id']==$r['requester_id']||$u['id']==$r['recipient_id'])){http_response_code(403);exit('Accès non autorisé.');}$rs=$pdo->prepare('SELECT rr.*,'.sql_full_name('u').' author FROM request_responses rr JOIN users u ON u.id=rr.author_id WHERE rr.request_id=? ORDER BY rr.created_at');$rs->execute([$id]);$history='';foreach($rs as $x)$history.='<li><strong>'.h($x['author']).'</strong> : '.h(str_replace('_',' ',$x['decision'])).' '.h($x['message']).'</li>';$can=$u['id']==$r['recipient_id']&&$r['status']==='en_attente';$form=$can?'<h2>Répondre</h2><form method="post">'.csrf_field().'<input type="hidden" name="action" value="respond"><input type="hidden" name="request_id" value="'.$id.'"><label>Décision<select name="decision"><option value="acceptee">Accepter</option><option value="refusee">Refuser</option><option value="contre_proposition">Proposer un ajustement</option></select></label>'.input('proposed_place','Autre lieu (optionnel)').input('proposed_time','Autre heure (optionnel)','', 'time').'<label>Message<textarea name="message"></textarea></label><button>Envoyer</button></form>':(($u['id']==$r['requester_id']&&$r['status']==='en_attente')?'<form method="post">'.csrf_field().'<input type="hidden" name="action" value="respond"><input type="hidden" name="request_id" value="'.$id.'"><input type="hidden" name="decision" value="annulee"><button>Annuler la demande</button></form>':'');layout('Demande','<h1>'.h($r['title']).'</h1><p><strong>'.h($r['requester']).'</strong> → <strong>'.h($r['recipient']).'</strong></p><p>'.h($r['pickup_place']).' à '.h($r['pickup_time']).'</p><p>'.h($r['message']).'</p><p>État : '.h(str_replace('_',' ',$r['status'])).'</p><ul>'.$history.'</ul>'.$form);exit; }
if ($page==='admin') { $a=require_admin();$members=$pdo->query('SELECT id,first_name,last_name,email,status,role FROM users ORDER BY role DESC,last_name')->fetchAll();$memberRows='';foreach($members as $m){$memberRows.='<tr><td>'.h($m['first_name'].' '.$m['last_name']).'</td><td>'.h($m['email']).'</td><td>'.h($m['status']).'</td><td>'.($m['role']==='member'?'<form method="post" class="inline">'.csrf_field().'<input type="hidden" name="action" value="member_status"><input type="hidden" name="user_id" value="'.$m['id'].'"><select name="status"><option value="active">Actif</option><option value="disabled">Désactivé</option></select><button>Modifier</button></form>':'Administrateur').'</td></tr>';}$events=$pdo->query('SELECT * FROM events ORDER BY starts_at DESC')->fetchAll();$eventRows='';foreach($events as $e)$eventRows.='<tr><td>'.h($e['title']).'</td><td>'.h($e['starts_at']).'</td><td>'.h($e['status']).'</td></tr>';$requests=$pdo->query('SELECT cr.id,cr.status,e.title FROM carpool_requests cr JOIN events e ON e.id=cr.event_id ORDER BY cr.updated_at DESC LIMIT 20')->fetchAll();$requestRows='';foreach($requests as $r)$requestRows.='<tr><td><a href="?page=request&id='.$r['id'].'">'.h($r['title']).'</a></td><td>'.h(str_replace('_',' ',$r['status'])).'</td></tr>';layout('Administration','<h1>Administration</h1><section><h2>Inviter un membre</h2><form method="post">'.csrf_field().'<input type="hidden" name="action" value="invite">'.input('email','E-mail','','email',true).'<button>Envoyer l’invitation</button></form></section><section><h2>Créer un événement</h2><form method="post">'.csrf_field().'<input type="hidden" name="action" value="event">'.input('title','Titre','','text',true).'<label>Type<select name="type"><option value="repetition">Répétition</option><option value="concert">Concert</option></select></label>'.input('starts_at','Date et heure','','datetime-local',true).input('location','Lieu','','text',true).'<label>Détails<textarea name="details"></textarea></label><input type="hidden" name="status" value="active"><button>Créer l’événement</button></form></section><section><h2>Membres</h2><table><tr><th>Nom</th><th>E-mail</th><th>État</th><th>Action</th></tr>'.$memberRows.'</table></section><section><h2>Événements</h2><table><tr><th>Titre</th><th>Date</th><th>État</th></tr>'.$eventRows.'</table></section><section><h2>Demandes récentes</h2><table><tr><th>Événement</th><th>État</th></tr>'.$requestRows.'</table></section>');exit; }
